package cn.tcm.platform.source;

import cn.tcm.platform.common.*;
import com.fasterxml.jackson.databind.JsonNode;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import java.nio.charset.StandardCharsets;
import java.util.*;
import static cn.tcm.platform.source.SourceAccess.*;

@Service
public class SourceReader {
    private final SourceAccess access;private final SourceRights rights;private final SourceReadingData data;private final SourceService sources;
    public SourceReader(SourceAccess a,SourceRights r,SourceReadingData d,SourceService s){access=a;rights=r;data=d;sources=s;}
    public Map<String,Object> edition(long actor,long document,Long requested){
        var d=rights.requireRead(actor,document);boolean privileged=rights.privileged(actor,d);
        Object pointer=privileged?d.get("active_reading_edition_id"):d.get("reviewed_reading_edition_id");
        Long id=requested==null?(pointer==null?null:Long.valueOf(pointer.toString())):requested;
        if(id==null)throw ApiException.conflict("资料尚未生成阅读版本，请构建或重试处理");
        if(!privileged&&!Objects.equals(id.toString(),Objects.toString(pointer,null)))throw ApiException.missing();
        var rows=access.db.queryForList("SELECT e.*,p.parse_version FROM source_reading_editions e JOIN document_parse_runs p ON p.id=e.processing_run_id WHERE e.id=? AND e.document_id=? AND e.status='READY'",id,document);
        if(rows.isEmpty())throw ApiException.missing();return rows.get(0);
    }
    private long number(Map<String,Object> m,String key){return ((Number)m.get(key)).longValue();}
    private Map<String,Object> unitView(Map<String,Object>u){return map("id",id(u.get("id")),"editionId",id(u.get("edition_id")),"unitNo",u.get("unit_no"),"unitType",u.get("unit_type"),"title",u.get("title"),"pageNumber",u.get("page_number"),"capabilities",data.decoded(u.get("capabilities"),Map.of()),"availableReadingModes",data.decoded(u.get("reading_modes"),List.of()),"warnings",data.decoded(u.get("warnings"),List.of()),"previewRef",u.get("preview_ref"));}
    public Map<String,Object> reader(long actor,long document,Long requested){
        var e=edition(actor,document,requested);var d=rights.requireRead(actor,document);long eid=number(e,"id");
        var ev=map("id",id(e.get("id")),"readingVersionNo",e.get("reading_version_no"),"parseRunId",id(e.get("parse_run_id")),"processingRunId",id(e.get("processing_run_id")),"parseVersion",e.get("parse_version"),"format",e.get("format"),"status",e.get("status"),"layoutMode",e.get("layout_mode"),"availableReadingModes",data.decoded(e.get("reading_modes"),List.of()),"capabilities",data.decoded(e.get("capabilities"),Map.of()),"metadata",data.decoded(e.get("metadata"),Map.of()),"warnings",data.decoded(e.get("warnings"),List.of()),"overallOutcome",e.get("overall_outcome"),"stages",data.decoded(e.get("stage_results"),Map.of()));
        var units=access.db.queryForList("SELECT * FROM source_reading_units WHERE edition_id=? ORDER BY unit_no",eid).stream().map(this::unitView).toList();
        var assets=access.db.queryForList("SELECT * FROM source_reading_assets WHERE edition_id=?",eid).stream().filter(a->a.get("mime_type").toString().startsWith("image/")).map(a->map("id",id(a.get("id")),"ref",a.get("asset_ref"),"mimeType",a.get("mime_type"),"kind",a.get("asset_kind"))).toList();
        return map("document",sources.view(d),"edition",ev,"outline",data.decoded(e.get("outline"),List.of()),"units",units,"assets",assets,"progress",progress(actor,document,eid),"capabilities",map("read",true,"extract",access.permission(actor,"contribution:submit")&&!("APPROVED".equals(d.get("review_state"))&&"REFERENCE_ONLY".equals(d.get("approved_use")))&&data.tree(e.get("capabilities")).path("preciseCitationSupported").asBoolean(),"download",rights.canDeliver(actor,d)));
    }
    public Map<String,Object> unit(long actor,long document,long unit,Long requested,String mode){var e=edition(actor,document,requested);var rows=access.db.queryForList("SELECT * FROM source_reading_units WHERE id=? AND edition_id=?",unit,e.get("id"));if(rows.isEmpty())throw ApiException.missing();var u=rows.get(0);
        if(mode!=null){boolean allowed=false;for(var m:data.tree(u.get("reading_modes")))if(mode.equals(m.asText()))allowed=true;if(!allowed)throw ApiException.invalid("当前单元不支持该阅读模式");}
        var out=unitView(u);out.put("nodes",data.decoded(u.get("nodes"),List.of()));out.put("blocks",access.db.queryForList("SELECT * FROM source_reading_blocks WHERE unit_id=? ORDER BY block_no",unit).stream().map(b->map("id",id(b.get("id")),"localId",b.get("local_id"),"blockNo",b.get("block_no"),"text",b.get("body"))).toList());return out;
    }
    public Map<String,Object> asset(long actor,long document,long asset){var rows=access.db.queryForList("SELECT a.* FROM source_reading_assets a JOIN source_reading_editions e ON e.id=a.edition_id WHERE a.id=? AND e.document_id=? AND a.mime_type IN ('image/png','image/jpeg')",asset,document);if(rows.isEmpty())throw ApiException.missing();var a=rows.get(0);edition(actor,document,number(a,"edition_id"));return a;}
    public PageResult<Map<String,Object>> search(long actor,long document,Long requested,String q,int page,int size){var e=edition(actor,document,requested);int offset=PageResult.offset(page,size);if(q==null||q.isBlank()||q.length()>200)throw ApiException.invalid("请输入200字以内搜索词");String query=q.strip();var hits=new ArrayList<Map<String,Object>>();
        var blocks=access.db.queryForList("SELECT b.*,u.unit_no,u.capabilities FROM source_reading_blocks b JOIN source_reading_units u ON u.id=b.unit_id WHERE b.edition_id=? ORDER BY u.unit_no,b.block_no",e.get("id"));
        for(var b:blocks){if(!data.tree(b.get("capabilities")).path("searchable").asBoolean())continue;String text=b.get("body").toString();int start=text.indexOf(query);if(start<0)continue;int cp=text.codePointCount(0,start);hits.add(map("unitId",id(b.get("unit_id")),"unitNo",b.get("unit_no"),"blockId",id(b.get("id")),"localId",b.get("local_id"),"offset",cp,"endOffset",cp+query.codePointCount(0,query.length()),"text",text));}
        return new PageResult<>(page,size,hits.size(),hits.subList(Math.min(offset,hits.size()),Math.min(offset+size,hits.size())));
    }
    public Map<String,Object> progress(long actor,long document,Long requested){var e=edition(actor,document,requested);var rows=access.db.queryForList("SELECT * FROM source_reading_progress WHERE user_id=? AND document_id=? AND edition_id=?",actor,document,e.get("id"));if(rows.isEmpty())return null;var p=rows.get(0);return map("editionId",id(p.get("edition_id")),"unitId",id(p.get("unit_id")),"blockId",id(p.get("block_id")),"offset",p.get("text_offset"),"pageNumber",p.get("page_number"),"fontSize",p.get("font_size"),"readingMode",p.get("reading_mode"),"lockVersion",p.get("lock_version"));}
    @Transactional public Map<String,Object> saveProgress(long actor,long document,JsonNode input){long eid=positive(input,"editionId"),uid=positive(input,"unitId");var u=unit(actor,document,uid,eid,input.path("readingMode").asText(null));int offset=input.path("offset").asInt(0),font=input.path("fontSize").asInt(18);if(offset<0||font<14||font>32)throw ApiException.invalid("阅读位置或字号无效");Long bid=input.hasNonNull("blockId")?positive(input,"blockId"):null;
        if(bid!=null){var bs=access.db.queryForList("SELECT body FROM source_reading_blocks WHERE id=? AND unit_id=? AND edition_id=?",String.class,bid,uid,eid);if(bs.isEmpty()||offset>bs.get(0).codePointCount(0,bs.get(0).length()))throw ApiException.invalid("原文位置无效");}else if(offset!=0)throw ApiException.invalid("文字位置须指定原文块");
        Integer page=input.hasNonNull("pageNumber")?input.path("pageNumber").asInt():null;if(page!=null&&!Objects.equals(page,u.get("pageNumber")))throw ApiException.invalid("页码不属于当前阅读单元");
        access.db.queryForObject("SELECT id FROM sys_users WHERE id=? FOR UPDATE",Long.class,actor);var current=access.db.queryForList("SELECT * FROM source_reading_progress WHERE user_id=? AND document_id=? AND edition_id=? FOR UPDATE",actor,document,eid);String mode=input.path("readingMode").asText(null);if(mode==null){var modes=(java.util.List<?>)u.get("availableReadingModes");if(modes.isEmpty())throw ApiException.invalid("No available reading mode");mode=modes.get(0).toString();}
        if(current.isEmpty()){if(input.hasNonNull("expectedVersion")&&input.path("expectedVersion").asInt()!=0)throw ApiException.conflict("阅读进度版本已变化");access.db.update("INSERT INTO source_reading_progress(user_id,document_id,edition_id,unit_id,block_id,text_offset,page_number,font_size,reading_mode) VALUES(?,?,?,?,?,?,?,?,?)",actor,document,eid,uid,bid,offset,page,font,mode);}else{int version=((Number)current.get(0).get("lock_version")).intValue();if(!input.hasNonNull("expectedVersion")||input.path("expectedVersion").asInt()!=version)throw ApiException.conflict("阅读进度已在其他窗口更新");access.db.update("UPDATE source_reading_progress SET unit_id=?,block_id=?,text_offset=?,page_number=?,font_size=?,reading_mode=?,lock_version=lock_version+1 WHERE id=?",uid,bid,offset,page,font,mode,current.get(0).get("id"));}return progress(actor,document,eid);
    }
    public static long positive(JsonNode n,String key){try{long v=Long.parseLong(n.path(key).asText());if(v>0)return v;}catch(Exception ignored){}throw ApiException.invalid(key+"无效");}
    public record Selection(long editionId,long parseRunId,String location,String quote,String hash,Map<String,Object> locator){}
    public Selection selection(long actor,long document,JsonNode input){var d=rights.requireRead(actor,document);if("APPROVED".equals(d.get("review_state"))&&"REFERENCE_ONLY".equals(d.get("approved_use")))throw ApiException.conflict("此来源仅供阅读参考，不支持精确文字引用");long eid=positive(input,"editionId");var e=edition(actor,document,eid);if(e.get("parse_run_id")==null)throw ApiException.invalid("此阅读版本不支持精确文字引用");return reconstruct(document,e,input.path("ranges"),input.path("quoteText").asText());}
    public Selection reconstruct(long document,Map<String,Object> e,JsonNode ranges,String claimed){if(!ranges.isArray()||ranges.isEmpty()||ranges.size()>100)throw ApiException.invalid("选文范围无效");long eid=number(e,"id");var parts=new ArrayList<String>();var safe=new ArrayList<Map<String,Object>>();long previousUnit=0;int previousBlock=0,previousEnd=-1;String location="";
        for(var r:ranges){long bid=positive(r,"blockId");var rows=access.db.queryForList("SELECT b.*,u.unit_no,u.title,u.page_number,u.capabilities FROM source_reading_blocks b JOIN source_reading_units u ON u.id=b.unit_id WHERE b.id=? AND b.edition_id=?",bid,eid);if(rows.isEmpty())throw ApiException.invalid("引用位置不属于此阅读版本");var b=rows.get(0);if(!data.tree(b.get("capabilities")).path("preciseCitationSupported").asBoolean())throw ApiException.invalid("此单元不支持精确引用");String text=b.get("body").toString();int count=text.codePointCount(0,text.length()),start=r.path("start").asInt(-1),end=r.path("end").asInt(-1),unit=((Number)b.get("unit_no")).intValue(),block=((Number)b.get("block_no")).intValue();
            if(start<0||end<=start||end>count||unit<previousUnit||unit==previousUnit&&(block<previousBlock||block==previousBlock&&start<previousEnd))throw ApiException.invalid("选文越界、重叠或顺序无效");previousUnit=unit;previousBlock=block;previousEnd=end;parts.add(text.substring(text.offsetByCodePoints(0,start),text.offsetByCodePoints(0,end)));safe.add(map("blockId",Long.toString(bid),"unitId",id(b.get("unit_id")),"localId",b.get("local_id"),"start",start,"end",end));if(location.isEmpty())location=b.get("title")+(b.get("page_number")==null?"":" / 第"+b.get("page_number")+"页");}
        String quote=String.join("\n",parts);if(quote.length()>20000||quote.isBlank()||!quote.equals(claimed))throw ApiException.invalid("引文与原文选择不一致或超限");return new Selection(eid,number(e,"parse_run_id"),location.length()>255?location.substring(0,255):location,quote,SourceFiles.hash(quote.getBytes(StandardCharsets.UTF_8)),map("schemaVersion",2,"editionId",Long.toString(eid),"ranges",safe));
    }
    @Transactional public Map<String,Object> excerpt(long actor,long document,JsonNode input){access.require(actor,"contribution:submit");var s=selection(actor,document,input);String key=SourceFiles.hash(data.encoded(s.locator()).getBytes(StandardCharsets.UTF_8));access.db.update("INSERT INTO source_reading_excerpts(user_id,document_id,edition_id,parse_run_id,locator,location_label,quote_text,quote_hash,selection_hash) VALUES(?,?,?,?,?,?,?,?,?) ON DUPLICATE KEY UPDATE id=id",actor,document,s.editionId(),s.parseRunId(),data.encoded(s.locator()),s.location(),s.quote(),s.hash(),key);return excerptView(access.db.queryForMap("SELECT x.*,d.title FROM source_reading_excerpts x JOIN source_documents d ON d.id=x.document_id WHERE x.user_id=? AND x.edition_id=? AND x.selection_hash=?",actor,s.editionId(),key));}
    public Map<String,Object> ownedExcerpt(long actor,long excerpt){var rows=access.db.queryForList("SELECT x.*,d.title,d.availability,d.review_state,d.submitted_by,d.quote_display_allowed,d.public_reading_allowed FROM source_reading_excerpts x JOIN source_documents d ON d.id=x.document_id WHERE x.id=? AND x.user_id=?",excerpt,actor);if(rows.isEmpty())throw ApiException.missing();var x=rows.get(0);if(!"ACTIVE".equals(x.get("availability"))||!rights.canRead(actor,x)&&!SourceRights.flag(x.get("quote_display_allowed")))throw ApiException.missing();return excerptView(x);}
    private Map<String,Object> excerptView(Map<String,Object>x){return map("id",id(x.get("id")),"excerptId",id(x.get("id")),"documentId",id(x.get("document_id")),"documentTitle",x.get("title"),"parseRunId",id(x.get("parse_run_id")),"readingEditionId",id(x.get("edition_id")),"locationLabel",x.get("location_label"),"quoteText",x.get("quote_text"),"quoteHash",x.get("quote_hash"),"locator",data.decoded(x.get("locator"),Map.of()));}
    public List<Map<String,Object>> excerpts(long actor,Long document){var rows=access.db.queryForList("SELECT x.id FROM source_reading_excerpts x WHERE x.user_id=?"+(document==null?"":" AND x.document_id=?")+" ORDER BY x.created_at DESC LIMIT 200",document==null?new Object[]{actor}:new Object[]{actor,document});var out=new ArrayList<Map<String,Object>>();for(var r:rows){try{out.add(ownedExcerpt(actor,number(r,"id")));}catch(ApiException ignored){}}return out;}
}
